-- SQL baseline (PostgreSQL 18). Forward-only: never edit after it is applied.
-- Phase B slice 3a (ADR-0006): the transactional outbox and the idempotency ledger.
-- ids are generated by the application (no DB defaults).

-- Cross-module side effects (CLAUDE.md §6). The writers are the roles that run use cases; the
-- dispatcher (PRD §4.5) is the only reader. Not a clinic-owned table: an event may have no
-- clinic (platform events), so the key is `id` alone. RLS still pins each writer's rows to its
-- own tenant context, so a clinic session cannot enqueue an event for another clinic.
CREATE TABLE outbox_events (
  id            uuid PRIMARY KEY,
  clinic_id     uuid NULL REFERENCES clinics (id),
  event_type    text NOT NULL CHECK (event_type ~ '^[a-z]+(_[a-z]+)*\.[a-z]+(_[a-z]+)*$'),
  payload       jsonb NOT NULL,
  created_at    timestamptz NOT NULL,
  dispatched_at timestamptz NULL
);
CREATE INDEX outbox_events_clinic_idx ON outbox_events (clinic_id);
CREATE INDEX outbox_events_pending_idx ON outbox_events (created_at) WHERE dispatched_at IS NULL;

ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE outbox_events FORCE ROW LEVEL SECURITY;
-- Writers: the event's clinic must be the transaction's clinic (NULL only with no clinic context).
CREATE POLICY outbox_events_writer_insert ON outbox_events FOR INSERT TO eyadex_app, eyadex_platform
  WITH CHECK (clinic_id IS NOT DISTINCT FROM NULLIF(current_setting('app.clinic_id', true), '')::uuid);
-- The dispatcher works across every clinic: it reads pending events and marks them sent.
CREATE POLICY outbox_events_dispatcher ON outbox_events TO eyadex_dispatcher
  USING (true) WITH CHECK (true);

-- Writers may only append: no read-back, no update, no delete.
GRANT INSERT ON outbox_events TO eyadex_app, eyadex_platform;
-- The dispatcher may scrub the payload (the sealed invitation link) once the email is sent.
GRANT SELECT, UPDATE (dispatched_at, payload) ON outbox_events TO eyadex_dispatcher;

-- Idempotency-Key ledger (PRD §4.12). `scope` names the operation and the caller, so two
-- callers can never collide on the same key. `request_hash` is a SHA-256 of the canonical body;
-- `response` holds identifiers only — never a token or a secret.
-- TODO(spec): retention of old keys (a worker sweep) is not decided yet.
CREATE TABLE idempotency_keys (
  scope        text NOT NULL CHECK (scope <> ''),
  key          text NOT NULL CHECK (length(key) BETWEEN 1 AND 200),
  request_hash text NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  response     jsonb NULL,
  created_at   timestamptz NOT NULL,
  PRIMARY KEY (scope, key)
);
-- Only platform use cases accept a key today; clinic use cases get their grant with their slice.
GRANT SELECT, INSERT, UPDATE (response) ON idempotency_keys TO eyadex_platform;
